-- MySQL-compatible seed script for placement detectors
-- Adapt column types and table name if your schema differs.

CREATE TABLE IF NOT EXISTS transactions_test_seed (
  tx_hash VARCHAR(128) PRIMARY KEY,
  sender VARCHAR(128) NOT NULL,
  receiver VARCHAR(128) NOT NULL,
  amount DECIMAL(30,8) DEFAULT 0,
  usd_value DECIMAL(30,2) DEFAULT 0,
  token VARCHAR(64),
  ts DATETIME,
  chain VARCHAR(64)
);

